# Health check probes.
#
# Demonstrates: HTTP health check with path and interval, TCP health check.
# Run with:  cca run examples/health-checks.ccattler
#            (requires real processes that listen on the declared ports)
#
# Expected: web instances are probed at GET /health every 10s.
#           database instances are probed via TCP connect every 5s.
#           Status output shows health=healthy or health=unhealthy per instance.

service web {
    image nginx:1.28
    instances 3
    expose 8080
    resources {
        cpu 500m
        memory 512Mi
    }
    health {
        http /health
        every 10s
    }
}

service database {
    image postgres:16
    instances 1
    expose 5432
    resources {
        cpu 1000m
        memory 2048Mi
    }
    health {
        tcp
        every 5s
    }
}

# Multiple services with different resource profiles.
#
# Demonstrates: two independent services, different instance counts,
#               different ports, different resource allocations.
# Run with:  cca apply examples/multi-service.ccattler
#
# Expected: web gets 4 instances spread across nodes, api gets 2.
#           Each service has its own resource footprint.

service web {
    image nginx:1.28
    instances 4
    expose 8080
    resources {
        cpu 500m
        memory 512Mi
    }
}

service api {
    image myapp:latest
    instances 2
    expose 3000
    resources {
        cpu 250m
        memory 256Mi
    }
}

# Persistent storage: volumes survive node moves.
#
# Demonstrates: volume declaration, service-to-volume binding, exclusive attach
#               (ReadWriteOnce), volume migration on node failure.
# Run with:  cca demo-storage   (built-in with node kill + volume migration)
#
# Expected: postgres gets 1 instance with volume pgdata attached at /var/lib/postgresql/data.
#           web runs 3 instances with no volume (unaffected by storage).
#           If the node running postgres dies, the volume detaches and reattaches
#           to the replacement instance on a surviving node.

volume pgdata {
    size 50Gi
    persistent true
}

service postgres {
    image postgres:16
    instances 1
    expose 5432
    resources {
        cpu 1000m
        memory 2048Mi
    }
    volume pgdata /var/lib/postgresql/data
}

service web {
    image nginx:1.28
    instances 3
    expose 8080
    resources {
        cpu 500m
        memory 512Mi
    }
}

service web {
    image nginx:1.28
    instances 2
    expose 80
    resources {
        cpu 500m
        memory 512Mi
    }
}

# Simple demo: runs 3 sleep processes.
# In production, image would be a container reference.
# For process runtime, image is the shell command to execute.

service web {
    image "sleep 300"
    instances 3
    expose 8080
    resources {
        cpu 500m
        memory 512Mi
    }
}
